import path from 'node:path';
import { app, type BrowserWindow } from 'electron';
import { setupIPC } from './ipc';
import { initLogger, LogLevel, setupLogIPC } from './lib/logger';
import { createWindow } from './window';

const isDev = process.argv.includes('--start-dev');

initLogger({
  level: isDev ? LogLevel.DEBUG : LogLevel.INFO,
  showSource: true,
  prettyPrint: true,
});

let mainWindow: BrowserWindow | null = null;

app.whenReady().then(() => {
  mainWindow = createWindow(isDev, mainWindow, process.cwd());
  setupIPC(mainWindow);
  setupLogIPC(mainWindow);
});

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') app.quit();
});

app.on('activate', () => {
  if (!mainWindow) mainWindow = createWindow(isDev, mainWindow, process.cwd());
});
